package com.example.techfix;
import android.content.Intent; import android.os.*; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.example.techfix.data.AppDatabase; import com.example.techfix.data.entity.User; import com.example.techfix.data.repository.UserRepository; import java.util.concurrent.*;
public class RegisterActivity extends AppCompatActivity {private final ExecutorService executor=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private UserRepository repo;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_register);repo=new UserRepository(AppDatabase.getDatabase(getApplicationContext()).userDao());EditText name=findViewById(R.id.etName),email=findViewById(R.id.etEmail),phone=findViewById(R.id.etPhone),password=findViewById(R.id.etPassword);findViewById(R.id.btnRegister).setOnClickListener(v->{String n=name.getText().toString().trim(),e=email.getText().toString().trim(),ph=phone.getText().toString().trim(),p=password.getText().toString();if(n.isEmpty()||e.isEmpty()||ph.isEmpty()||p.isEmpty()){Toast.makeText(this,"Please fill in all fields",Toast.LENGTH_SHORT).show();return;}if(p.length()<6){Toast.makeText(this,"Password must be at least 6 characters",Toast.LENGTH_SHORT).show();return;}executor.execute(()->{try{User u=repo.register(n,e,p,ph);main.post(()->{Toast.makeText(this,"Account created! Welcome, "+u.getName(),Toast.LENGTH_SHORT).show();Intent i=new Intent(this,HomeActivity.class);i.putExtra("USER_NAME",u.getName());i.putExtra("USER_ID",u.getUserId());startActivity(i);finish();});}catch(Exception ex){main.post(()->Toast.makeText(this,ex.getMessage(),Toast.LENGTH_SHORT).show());}});});findViewById(R.id.tvGoToLogin).setOnClickListener(v->startActivity(new Intent(this,LoginActivity.class)));} @Override protected void onDestroy(){executor.shutdown();super.onDestroy();}}
